import{_ as e,o as d,c as r,ag as i}from"./chunks/framework.Drp2S_UI.js";const o=JSON.parse('{"title":"Benchmark：输入与持续删除性能","description":"","frontmatter":{},"headers":[],"relativePath":"guide/benchmark.md","filePath":"guide/benchmark.md","lastUpdated":1792752159000}'),l={name:"guide/benchmark.md"};function a(g,t,s,n,h,y){return d(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="benchmark-输入与持续删除性能" tabindex="-1">Benchmark：输入与持续删除性能 <a class="header-anchor" href="#benchmark-输入与持续删除性能" aria-label="Permalink to &quot;Benchmark：输入与持续删除性能&quot;">​</a></h1><p>更新日期：2026-10-23。包含 PERF-01 初始基线、PERF-21（本次修复前）及位置/查询增量提交、持续删除与 Worker 恢复修复后的结果。 默认 baseline 不变，以下优化来自显式实验配置。实现与边界见<a href="./lab.html">实验配置与回退</a>。</p><h2 id="测量口径" tabindex="-1">测量口径 <a class="header-anchor" href="#测量口径" aria-label="Permalink to &quot;测量口径&quot;">​</a></h2><p>同机 Apple M1 Pro / 8 logical CPUs / 16 GiB，Darwin 25.4.0，Node 24.19.0。字体为 NotoNaskhArabic-Regular.ttf，SHA256 <code>67b5a525a661b607971fbd3f96a81b89d3a768e74534fca84f18ac97e6fab72f</code>。</p><p>历史 Chrome 为 155.0.8059.85，本次为 155.0.8059.86。因此为同机同负载历史趋势，<strong>不是浏览器版本完全相同的严格 A/B</strong>，不能将全部时差唯一归因于代码。</p><p>标准负载为 middle / paging / history on / 段落缓存 off / DPR 1 / warmup 1 / 2Hz × 10s，每配置 20 次操作。初始基线一轮，修复前后各三轮；固定 trial 0 比较，不挑最快轮，三轮范围另列。输入取 input handler，删除取 keydown handler。单位为 ms，降低比例为 <code>(修复前 - 本次) / 修复前</code>，负数表示耗时增加。</p><p>geometry 为事件到几何提交的代理值，offer→geometry 含驱动排队，均不等于屏幕呈现延迟。阶段 inclusive 时间存在嵌套，不可相加。</p><h2 id="初始基线与两轮优化" tabindex="-1">初始基线与两轮优化 <a class="header-anchor" href="#初始基线与两轮优化" aria-label="Permalink to &quot;初始基线与两轮优化&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>操作</th><th style="text-align:right;">初始 P50</th><th style="text-align:right;">PERF-21 P50</th><th style="text-align:right;">本次 P50</th><th style="text-align:right;">相比 PERF-21 降低</th></tr></thead><tbody><tr><td>100 段</td><td>input</td><td style="text-align:right;">339.6</td><td style="text-align:right;">30.1</td><td style="text-align:right;">6.3</td><td style="text-align:right;">79.1%</td></tr><tr><td>100 段</td><td>backspace</td><td style="text-align:right;">357.1</td><td style="text-align:right;">30.7</td><td style="text-align:right;">7.5</td><td style="text-align:right;">75.6%</td></tr><tr><td>100 段</td><td>delete</td><td style="text-align:right;">352.6</td><td style="text-align:right;">31.2</td><td style="text-align:right;">7.2</td><td style="text-align:right;">76.9%</td></tr><tr><td>1000 段</td><td>input</td><td style="text-align:right;">5296.0</td><td style="text-align:right;">287.3</td><td style="text-align:right;">34.8</td><td style="text-align:right;">87.9%</td></tr><tr><td>1000 段</td><td>backspace</td><td style="text-align:right;">5349.9</td><td style="text-align:right;">277.8</td><td style="text-align:right;">32.1</td><td style="text-align:right;">88.4%</td></tr><tr><td>1000 段</td><td>delete</td><td style="text-align:right;">5358.3</td><td style="text-align:right;">267.0</td><td style="text-align:right;">35.3</td><td style="text-align:right;">86.8%</td></tr><tr><td>超长单段</td><td>input</td><td style="text-align:right;">471.1</td><td style="text-align:right;">197.1</td><td style="text-align:right;">189.8</td><td style="text-align:right;">3.7%</td></tr><tr><td>超长单段</td><td>backspace</td><td style="text-align:right;">480.2</td><td style="text-align:right;">194.0</td><td style="text-align:right;">194.7</td><td style="text-align:right;">-0.4%</td></tr><tr><td>超长单段</td><td>delete</td><td style="text-align:right;">469.7</td><td style="text-align:right;">190.5</td><td style="text-align:right;">191.9</td><td style="text-align:right;">-0.7%</td></tr><tr><td>大表格</td><td>input</td><td style="text-align:right;">42.4</td><td style="text-align:right;">19.9</td><td style="text-align:right;">20.0</td><td style="text-align:right;">-0.5%</td></tr><tr><td>大表格</td><td>backspace</td><td style="text-align:right;">39.5</td><td style="text-align:right;">19.1</td><td style="text-align:right;">21.7</td><td style="text-align:right;">-13.6%</td></tr><tr><td>大表格</td><td>delete</td><td style="text-align:right;">43.1</td><td style="text-align:right;">20.8</td><td style="text-align:right;">20.7</td><td style="text-align:right;">0.5%</td></tr></tbody></table><h2 id="本次三轮波动及尾延迟" tabindex="-1">本次三轮波动及尾延迟 <a class="header-anchor" href="#本次三轮波动及尾延迟" aria-label="Permalink to &quot;本次三轮波动及尾延迟&quot;">​</a></h2><p>尾延迟取各轮对应百分位的最大值，不是合并分布；保留慢样本。</p><table tabindex="0"><thead><tr><th>文档</th><th>操作</th><th style="text-align:right;">P50 范围</th><th style="text-align:right;">handler P95 / P99 / max（各轮最大）</th><th style="text-align:right;">geometry P95（各轮最大）</th></tr></thead><tbody><tr><td>100 段</td><td>input</td><td style="text-align:right;">6.3–8.0</td><td style="text-align:right;">12.4 / 13.1 / 13.1</td><td style="text-align:right;">12.3</td></tr><tr><td>100 段</td><td>backspace</td><td style="text-align:right;">6.9–8.6</td><td style="text-align:right;">13.3 / 88.9 / 88.9</td><td style="text-align:right;">13.2</td></tr><tr><td>100 段</td><td>delete</td><td style="text-align:right;">7.0–7.5</td><td style="text-align:right;">21.9 / 92.8 / 92.8</td><td style="text-align:right;">21.8</td></tr><tr><td>1000 段</td><td>input</td><td style="text-align:right;">34.0–35.3</td><td style="text-align:right;">49.3 / 59.5 / 59.5</td><td style="text-align:right;">49.3</td></tr><tr><td>1000 段</td><td>backspace</td><td style="text-align:right;">32.1–34.5</td><td style="text-align:right;">50.1 / 1491.8 / 1491.8</td><td style="text-align:right;">50.0</td></tr><tr><td>1000 段</td><td>delete</td><td style="text-align:right;">32.4–35.9</td><td style="text-align:right;">98.3 / 1435.5 / 1435.5</td><td style="text-align:right;">98.3</td></tr><tr><td>超长单段</td><td>input</td><td style="text-align:right;">189.8–190.5</td><td style="text-align:right;">211.0 / 223.1 / 223.1</td><td style="text-align:right;">210.9</td></tr><tr><td>超长单段</td><td>backspace</td><td style="text-align:right;">189.5–194.7</td><td style="text-align:right;">206.5 / 214.1 / 214.1</td><td style="text-align:right;">206.3</td></tr><tr><td>超长单段</td><td>delete</td><td style="text-align:right;">191.0–191.9</td><td style="text-align:right;">209.6 / 211.2 / 211.2</td><td style="text-align:right;">209.6</td></tr><tr><td>大表格</td><td>input</td><td style="text-align:right;">19.9–23.5</td><td style="text-align:right;">127.3 / 247.1 / 247.1</td><td style="text-align:right;">127.3</td></tr><tr><td>大表格</td><td>backspace</td><td style="text-align:right;">18.9–21.7</td><td style="text-align:right;">32.2 / 37.1 / 37.1</td><td style="text-align:right;">32.1</td></tr><tr><td>大表格</td><td>delete</td><td style="text-align:right;">20.1–20.7</td><td style="text-align:right;">33.3 / 40.0 / 40.0</td><td style="text-align:right;">33.3</td></tr></tbody></table><h2 id="位置与查询工作量" tabindex="-1">位置与查询工作量 <a class="header-anchor" href="#位置与查询工作量" aria-label="Permalink to &quot;位置与查询工作量&quot;">​</a></h2><p>千段输入 trial 0，每键平均 inclusive 时间；queryIndexBuild 包含在 positions 内。</p><table tabindex="0"><thead><tr><th>阶段</th><th style="text-align:right;">PERF-21</th><th style="text-align:right;">本次</th><th style="text-align:right;">降低</th></tr></thead><tbody><tr><td>positions</td><td style="text-align:right;">281.64</td><td style="text-align:right;">8.43</td><td style="text-align:right;">97.0%</td></tr><tr><td>queryIndexBuild</td><td style="text-align:right;">54.41</td><td style="text-align:right;">2.29</td><td style="text-align:right;">95.8%</td></tr><tr><td>flow</td><td style="text-align:right;">15.87</td><td style="text-align:right;">17.31</td><td style="text-align:right;">-9.1%</td></tr></tbody></table><p>千段输入 20 次新增计算 2730 个位置元素，复用 776180 个位置元素；计数为窗口增量，不含仅恢复前缀页引用。测试另确认千行 source 平移不重建字符表，首次查询复用本次提交的行几何。全局位置元数据、行目录及段落目录仍需遍历，不宣称常数时间提交。</p><h2 id="持续输入、删除和-worker" tabindex="-1">持续输入、删除和 Worker <a class="header-anchor" href="#持续输入、删除和-worker" aria-label="Permalink to &quot;持续输入、删除和 Worker&quot;">​</a></h2><p>以下均为 30Hz；百段长压力 30 秒/900 次，千段和 transfer 为 10 秒/300 次。不同文档、时长和容量不混合计算收益。PERF-01 百段 300 次 Backspace 的 116 秒排空仅为原始压力基线，不直接与 900 次样本计算降幅。</p><table tabindex="0"><thead><tr><th>本次配置 / 动作 / trial</th><th style="text-align:right;">次数</th><th style="text-align:right;">handler P95</th><th style="text-align:right;">geometry P95</th><th style="text-align:right;">offer→geometry P95</th><th style="text-align:right;">排空 ms</th><th>ready / needsResync</th></tr></thead><tbody><tr><td>千段 Worker / 10s / input / 0</td><td style="text-align:right;">300</td><td style="text-align:right;">2.6</td><td style="text-align:right;">148.7</td><td style="text-align:right;">1356.6</td><td style="text-align:right;">11392.0</td><td>true / false</td></tr><tr><td>千段 Worker / 10s / input / 1</td><td style="text-align:right;">300</td><td style="text-align:right;">2.5</td><td style="text-align:right;">1308.2</td><td style="text-align:right;">2214.5</td><td style="text-align:right;">10958.3</td><td>true / false</td></tr><tr><td>千段 Worker / 10s / input / 2</td><td style="text-align:right;">300</td><td style="text-align:right;">2.4</td><td style="text-align:right;">1313.5</td><td style="text-align:right;">2177.6</td><td style="text-align:right;">10906.7</td><td>true / false</td></tr><tr><td>百段 Worker / 30s / input / 0</td><td style="text-align:right;">900</td><td style="text-align:right;">5.8</td><td style="text-align:right;">179.3</td><td style="text-align:right;">217.1</td><td style="text-align:right;">30021.0</td><td>true / false</td></tr><tr><td>百段 Worker / 30s / backspace / 0</td><td style="text-align:right;">900</td><td style="text-align:right;">25.5</td><td style="text-align:right;">25.4</td><td style="text-align:right;">72.4</td><td style="text-align:right;">30351.1</td><td>true / false</td></tr><tr><td>百段 transfer / 10s / input / 0</td><td style="text-align:right;">300</td><td style="text-align:right;">2.9</td><td style="text-align:right;">138.2</td><td style="text-align:right;">161.6</td><td style="text-align:right;">10001.5</td><td>true / false</td></tr><tr><td>百段 transfer / 10s / input / 1</td><td style="text-align:right;">300</td><td style="text-align:right;">2.6</td><td style="text-align:right;">144.3</td><td style="text-align:right;">160.1</td><td style="text-align:right;">10001.7</td><td>true / false</td></tr><tr><td>百段 transfer / 10s / input / 2</td><td style="text-align:right;">300</td><td style="text-align:right;">3.0</td><td style="text-align:right;">143.3</td><td style="text-align:right;">172.7</td><td style="text-align:right;">10001.1</td><td>true / false</td></tr><tr><td>百段 transfer / 10s / backspace / 0</td><td style="text-align:right;">300</td><td style="text-align:right;">11.6</td><td style="text-align:right;">11.5</td><td style="text-align:right;">21.5</td><td style="text-align:right;">10001.4</td><td>true / false</td></tr><tr><td>百段 transfer / 10s / backspace / 1</td><td style="text-align:right;">300</td><td style="text-align:right;">12.4</td><td style="text-align:right;">12.3</td><td style="text-align:right;">25.9</td><td style="text-align:right;">10001.5</td><td>true / false</td></tr><tr><td>百段 transfer / 10s / backspace / 2</td><td style="text-align:right;">300</td><td style="text-align:right;">12.2</td><td style="text-align:right;">12.1</td><td style="text-align:right;">23.2</td><td style="text-align:right;">10000.4</td><td>true / false</td></tr></tbody></table><p>百段 30 秒 Backspace：handler P95 67.5 → 25.5ms，offer→geometry P95 6718.4 → 72.4ms，排空 36.13 → 30.35s。修复前 ready=false / needsResync=true；本次 ready=true / needsResync=false，请求 0、缓冲事务 0。本次未记录后台故障，会话启动 1 次（含首次启动），最大缓冲 25 条事务；完整 undo/redo 核对通过，历史新增 1 组。</p><p>删除同步提交增量几何、合并 paint；输入仍可异步排版，镜像编辑有序批量确认。超限或故障后由当前权威模型重建镜像，不丢已确认编辑。</p><h2 id="验证与发布状态" tabindex="-1">验证与发布状态 <a class="header-anchor" href="#验证与发布状态" aria-label="Permalink to &quot;验证与发布状态&quot;">​</a></h2><p>完整 Vitest 169 文件 / 1072 项通过；最终几何基准、销毁和排空边界修正后，4 文件 / 50 项回归再次通过。TypeScript、ESLint 和最终库构建通过。最终 Chrome 六组四模式差分、348 次结构比较及逐通道导出像素比较通过，含混排、RTL、表格、Unicode、历史、crash 与编辑队列预算不足后的恢复，无 pageerror。</p><p>固定预算仍为 handler P95 ≤8ms、geometry P95 ≤32ms，部分文档和压力负载仍超过预算，发布状态保持 <strong>hold</strong>。默认 baseline 不变，sync opt-in、Worker 实验、transfer 暂缓。超长段落整段排版和全局元数据仍有成本。千段 30Hz 输入中 flow 窗口累计仍为约 8.2–8.5 秒，两轮 geometry P95 仍约 1.3 秒；不能把位置阶段的改善当作高频输入全链路已达标。真实系统 IME/长按、屏幕呈现和长期原生/WASM/GPU 内存待验收；历史其他浏览器结果不替代本次复验。</p><p>六轮实际 create/edit/destroy 复验通过：销毁后 Worker、canvas、observer、待处理请求与路径缓存清空。强制 GC 页面 JS heap 为 14223020–14232228 bytes（约 13.56–13.57MiB），只支持短期 JS 生命周期结论，不证明长期原生/WASM/GPU 内存稳定。</p><h2 id="保留数据" tabindex="-1">保留数据 <a class="header-anchor" href="#保留数据" aria-label="Permalink to &quot;保留数据&quot;">​</a></h2><p>只保留初始基线、本次修复前基线和最终有效优化数据；中途失败/中间版本、截图、构建日志及临时对照不入库。本次最终合计 50 个场景 / 5280 次操作。最终 JSON 保留环境、sourceHashes、事件、阶段、队列和正确性结果，源哈希已核对。</p><ul><li><a href="performance-baselines/perf01-2026-10-22.json">初始标准</a>、<a href="performance-baselines/perf01-pressure-2026-10-22.json">初始压力</a></li><li><a href="performance-baselines/perf21-sync-2026-10-23.json">修复前同步</a>、<a href="performance-baselines/perf21-worker-long-pressure-2026-10-23.json">修复前持续编辑</a></li><li><a href="performance-baselines/perf-position-worker-sync-2026-10-23.json">本次同步三轮</a></li><li><a href="performance-baselines/perf-position-worker-long-2026-10-23.json">本次持续输入与删除</a></li><li><a href="performance-baselines/perf-position-worker-1000-2026-10-23.json">本次千段 Worker 压力</a></li><li><a href="performance-baselines/perf-position-worker-transfer-2026-10-23.json">本次 transfer 压力</a></li><li><a href="performance-baselines/perf-position-worker-uninstrumented-2026-10-23.json">本次无插桩对照</a></li></ul><p>验收清单引用最终数据，自动化日志须按<a href="./engineering-records.html">测试与验收流程</a>重新补齐；不能据历史摘要提升为 pass。</p>',29)])])}const p=e(l,[["render",a]]);export{o as __pageData,p as default};
